# owner: platform
"""Weekly timesheet rows, one line per worker."""

from typing import Dict, List
from hourglass.models import Shift
from collections import defaultdict

MINUTES_PER_HOUR = 60
Groups = Dict[str, List[Shift]]

# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    if not shifts:
        raise ValueError("no shifts given")
    return format_rows(group_workers(shifts))

# ---
def group_workers(shifts: List[Shift]) -> Groups:
    """Every shift for each trimmed worker name."""
    groups = defaultdict(list)
    for shift in shifts:
        groups[worker_name(shift)].append(shift)
    return dict(groups)

# ---
def worker_name(shift: Shift) -> str:
    """Trimmed worker name. Blank raises ValueError."""
    name = shift.worker.strip()
    if not name:
        raise ValueError(f"blank worker in {shift}")
    return name

# ---
def format_rows(groups: Groups) -> List[str]:
    """One line per worker, busiest first."""
    names = busiest_first(groups)
    return [
        format_row(name, groups[name]) for name in names
    ]

# ---
def busiest_first(groups: Groups) -> List[str]:
    """Names with the most minutes first, then by name."""
    return sorted(
        groups,
        key=lambda name: (-minutes_in(groups[name]), name),
    )

# ---
def minutes_in(group: List[Shift]) -> int:
    """Total scheduled minutes across a worker's shifts."""
    return sum(shift.span.minutes for shift in group)

# ---
def format_row(name: str, group: List[Shift]) -> str:
    """One row, such as Brisa, 3 shifts, 18.0 hours."""
    count = len(group)
    hours = minutes_in(group) / MINUTES_PER_HOUR
    noun = "shift" if count == 1 else "shifts"
    return f"{name}, {count} {noun}, {hours:.1f} hours"
